//── Callback ──────────────────────────────────────────────────────────────────
static void hkv_arrhythmia_test_stimulus_callback(
    int32_t op,
    hkv_arrhythmia_operator_state_t state,
    int32_t status,
    void *user_data
) {
    (void)user_data;
    if (state == hkv_arrhythmia_op_state_init_finished) {
        HKV_ARRHYTHMIA_PRINTF("Operator %ld init finished with status %ld\n", (long)op, (long)status);
    }
    if (state == hkv_arrhythmia_op_state_run_finished) {
        HKV_ARRHYTHMIA_PRINTF("Operator %ld run finished with status %ld\n", (long)op, (long)status);
    }
}


