{
    int32_t result = 0;
    const int num_iterations = 1;
    const int have_cycle_counter = hkv_arrhythmia_test_cycle_counter_enable();
    void (*saved_callback)(int32_t, hkv_arrhythmia_operator_state_t, int32_t, void *) = hkv_arrhythmia_test_stimulus_context.callback;
    uint64_t model_run_cycles_total = 0;

    if (have_cycle_counter) {
        hkv_arrhythmia_test_stimulus_context.callback = NULL;
    }

    // Run the model N times on the same stimulus
    for (int iter = 0; iter < num_iterations; iter++) {
        uint32_t cycle_start = 0;
        uint32_t cycle_end = 0;

        // Copy input tensors to context (before each iteration to ensure input persists)
    arm_memcpy_s8(
        hkv_arrhythmia_test_stimulus_context.inputs[0].data,
        (int8_t *)hkv_arrhythmia_test_stimulus_input_0,
        2000
    );

        if (have_cycle_counter) {
            cycle_start = hkv_arrhythmia_test_cycle_counter_read();
        }
        result = hkv_arrhythmia_model_run(&hkv_arrhythmia_test_stimulus_context);
        if (have_cycle_counter) {
            cycle_end = hkv_arrhythmia_test_cycle_counter_read();
            model_run_cycles_total += hkv_arrhythmia_test_cycle_counter_delta(cycle_start, cycle_end);
        }
        if (result != 0) {
            HKV_ARRHYTHMIA_PRINTF("Model run failed with status %ld (iteration %d)\n", (long)result, iter);
            hkv_arrhythmia_test_stimulus_context.callback = saved_callback;
            return result;
        }
    }

    if (have_cycle_counter) {
        const uint64_t cycles_per_iter = (num_iterations > 0)
            ? (model_run_cycles_total / (uint64_t)num_iterations)
            : 0;
        HKV_ARRHYTHMIA_PRINTF(
            "HELIA_E2E_METRIC counter=%s model_run_cycles_total=%llu model_run_cycles_per_iter=%llu iterations=%d\n",
            hkv_arrhythmia_test_counter_kind == hkv_arrhythmia_test_counter_pmu ? "pmu" :
            (hkv_arrhythmia_test_counter_kind == hkv_arrhythmia_test_counter_dwt ? "dwt" : "systick"),
            (unsigned long long)model_run_cycles_total,
            (unsigned long long)cycles_per_iter,
            num_iterations
        );
    } else {
        HKV_ARRHYTHMIA_PRINTF("HELIA_E2E_METRIC model_run_cycles_unavailable=1 iterations=%d\n", num_iterations);
    }

    hkv_arrhythmia_test_stimulus_context.callback = saved_callback;

    // Verify outputs once after all iterations
    float *act_0 = (float *)hkv_arrhythmia_test_stimulus_context.outputs[0].data;
    float *exp_0 = (float *)hkv_arrhythmia_test_stimulus_golden_0;
    for (int i = 0; i < 4; i++) {
        float act = (float)act_0[i];
        float exp = (float)exp_0[i];
        // Finite-aware oracle: a NaN ``diff`` makes ``diff > tol`` false, so a
        // plain magnitude check would silently accept NaN/unexpected-Inf
        // actuals against a finite expected value. Compare by expected class.
        int mismatch;
        if (isnan(exp)) {
            mismatch = !isnan(act);
        } else if (isinf(exp)) {
            mismatch = !(isinf(act) && ((act > 0.0f) == (exp > 0.0f)));
        } else {
            // Finite expected: any NaN/Inf actual fails; ``!(<=)`` also catches
            // the NaN ``diff`` case where ``>`` would wrongly pass.
            mismatch = !(fabsf(act - exp) <= (float)0.008);
        }
        if (mismatch) {
            HKV_ARRHYTHMIA_PRINTF("Output mismatch at index [%d][%d]: expected %f, got %f\n", 0, i, exp, act);
            result = 1;
        }
    }

    // Check for errors
    if (result == 0) {
        HKV_ARRHYTHMIA_PRINTF("Test passed!\n");
    } else {
        HKV_ARRHYTHMIA_PRINTF("Test failed!\n");
    }
    return result;

}